# Ruta 24 (the bridge of five, C2, contract 31), 14 x 46. column = i, row = j. Ciudad Marea's north gate arrives at the south edge (j = 45), Ruta 25 is the north edge (j = 0).
# Look (the user's variant A of tools/c2_mock.py, "Rutas 24-25"): a LONG PLANK BRIDGE (j = 12 .. 39, two lanes, planks across) over the open SEA (foam on the shores, 2 frames), sailboats and rocks
# in the water, a beach with beach grass at the south end, coastal grass with tall grass at the north end. FIVE trainers stand on the bridge, alternately on its two lanes (the west ones look S, the
# east ones look W, range 2): the hero has to change lane at each one and a beaten trainer never closes the bridge. The reward at the end: the recruiter's Gold Chunk (contract 80; Disc 03 moved to Ruta 25).
@map ruta_24
@size 14 46
@interior no
@area ruta_24
@bg 0
@fill grass
@spawn south 6 44 N             # arriving from Ciudad Marea
@spawn north 6 1 S              # arriving from Ruta 25
# (contract 80): the five bridge trainers keep their old automatic flags (131 .. 135: the numbers are in the legend now, so a script can read them); the recruiter at the north end checks all five.
@flag br5 131
@flag br4 132
@flag br3 133
@flag br2 134
@flag br1 135
@flag nugget_given 224          # the recruiter handed over the Gold Chunk
@flag recr_done 225             # the recruiter was beaten (and left)
@encounters grass rate=20      # Route 24 / 25: a creature, the bell-flower, ... + the rare dozing sprite
  mossbud 15 18 40
  flitter 14 17 20
  muncrit 14 17 15
  jabbird 15 18 15
  quillix 14 17 5
  dozelf 15 17 5
@end
# Open ground (contract 63, normal route): a step onto plain ground (not tall grass, water, a door, a ledge, an arrow floor) rolls this table when rand8 < 4 (4/256 per step).
@open_rate 4
# Roaming wild creatures (contract 55, rollout in 63): 3 creatures of this table wander the open ground (not the tall grass); touching one starts that wild battle.
@roam 3 table=grass period=1800
@legend
  .  tile=grass
  g  tile=tall_grass
  s  tile=sand
  w  tile=sea_o
  V  tile=sea_bl
  W  tile=sea_tr
  a  tile=plank_tl
  c  tile=plank_br
  S  tile=sea_o object=sea_rock_b
  Z  tile=sea_o object=sailboat
  b  tile=sand object=beach_grass
  q  tile=sand object=log
  B  object=rock
  T  object=bush
  G  tile=sand object=sign interact=look text=ruta24.sign
  n  tile=grass
  d  tile=sand
  Y  tile=grass npc=vertice id=recruiter face=S script=recruiter hide_flag=recr_done   # the Vertice recruiter of the bridge (replaces the Disc 03 pouch, which moved to Ruta 25)
  1  tile=plank_tl npc=explorador id=b1 face=S trainer=explorador_r24a range=2 beaten_flag=br1 text=tr.explorador_r24a.pre after=tr.explorador_r24a.after
  2  tile=plank_br npc=chica id=b2 face=W trainer=chica_r24 range=2 beaten_flag=br2 text=tr.chica_r24.pre after=tr.chica_r24.after
  3  tile=plank_tl npc=cazabichos id=b3 face=S trainer=cazabichos_r24 range=2 beaten_flag=br3 text=tr.cazabichos_r24.pre after=tr.cazabichos_r24.after
  4  tile=plank_br npc=explorador id=b4 face=W trainer=explorador_r24b range=2 beaten_flag=br4 text=tr.explorador_r24b.pre after=tr.explorador_r24b.after
  5  tile=plank_tl npc=vertice id=b5 face=S trainer=vertice_r24 range=2 beaten_flag=br5 text=tr.vertice_r24.pre after=tr.vertice_r24.after
  e  tile=sand item=disc_46
@grid
