@warp n -> ruta_25 spawn=south
@warp d -> ciudad_marea spawn=north
# (contract 80), the reward of bridge of five: the recruiter of the other team at its end. Once the five trainers are beaten he congratulates the hero and GIVES the Gold Chunk (a full bag: he waits), then asks him to join Vertice
# (YES and NO both end in the fight), battles him (trainer vertice_recluta) and, beaten, leaves for good (flag recr_done hides him). A lost fight is the blackout; he is still there and fights again.
@script recruiter npc
    npc_face_hero recruiter
    jnf br1 wait
    jnf br2 wait
    jnf br3 wait
    jnf br4 wait
    jnf br5 wait
    jf nugget_given retry
    say extra.recr.hello
    give_item trozo_oro 1
    jv 0 0 full
    item_var 0 trozo_oro
    say gl.gift
    setf nugget_given
    jmp join
  retry:
    say extra.recr.again
  join:
    ask extra.recr.join
    jv 0 1 yes
    say extra.recr.no
    jmp fight
  yes:
    say extra.recr.yes
  fight:
    battle vertice_recluta 0
    jv 0 1 won
    blackout
    end
  won:
    say extra.recr.lose
    npc_walk recruiter NE 4
    npc_hide recruiter
    setf recr_done
    end
  full:
    say gl.found.full
    end
  wait:
    say extra.recr.wait
@end
